// Serve only the two Metro-packaged viewers. None of these private URLs can fall back to a network request.
@Override
public android.webkit.WebResourceResponse shouldInterceptRequest(WebView view, WebResourceRequest request) {
    android.net.Uri uri = request.getUrl();
    String path = uri.getPath();
    if (!"appassets.androidplatform.net".equalsIgnoreCase(uri.getHost())
            || path == null || !path.startsWith("/topictrail/reader/")) {
        return super.shouldInterceptRequest(view, request);
    }

    String name = null;
    boolean readerRequest = false;
    for (java.util.Map.Entry<String, String> header : request.getRequestHeaders().entrySet()) {
        if ("X-TopicTrail-Reader".equalsIgnoreCase(header.getKey()) && "1".equals(header.getValue())) {
            readerRequest = true;
            break;
        }
    }
    if (readerRequest && request.isForMainFrame() && "GET".equals(request.getMethod())) {
        if ("https://appassets.androidplatform.net/topictrail/reader/pdf.html".equals(uri.toString())) {
            name = "assets_reader_viewer";
        } else if ("https://appassets.androidplatform.net/topictrail/reader/office.html".equals(uri.toString())) {
            name = "assets_reader_officeviewer";
        }
    }
    android.content.Context context = view.getContext();
    int id = name == null ? 0 : context.getResources().getIdentifier(name, "raw", context.getPackageName());
    if (id != 0) {
        try {
            return new android.webkit.WebResourceResponse("text/html", "UTF-8", 200, "OK",
                    java.util.Collections.singletonMap("Cache-Control", "no-store"),
                    context.getResources().openRawResource(id));
        } catch (android.content.res.Resources.NotFoundException ignored) {
            // A missing packaged asset must stay offline.
        }
    }
    return new android.webkit.WebResourceResponse("text/plain", "UTF-8", 404, "Not Found",
            java.util.Collections.singletonMap("Cache-Control", "no-store"),
            new java.io.ByteArrayInputStream(new byte[0]));
}

